 *
 * pxwrap — the wrapped cross-privilege frame-probe regression (differential).
 *
 * A cross-privilege delivery whose new TSS stack WRAPS its stack-pointer
 * window (B=0: SP < frame size, offsets wrap at 64 KiB; B=1: ESP < frame
 * size, offsets wrap at 4 GiB) occupies two disjoint offset chunks and can
 * touch up to four pages.  S_INT_PROBE must enumerate EVERY one of them in
 * push order before the staged SS/CPL commit.  This image drives the full
 * matrix generated by gen_cases.py (case_table, 16 bytes per case):
 *
 *   group 1: B=0, 16-bit interrupt AND trap gates, with and without an
 *            error code; SP from 0 through the frame size; SS.base low-12 in
 *            {0x000, 0xFF0, 0xFFC}; every touched page denied in turn.
 *   group 2: B=1, ESP0 < frame size (the 4 GiB wrap), incl. the
 *            maximal-page-count 140-byte call-gate frame on a flat stack.
 *   group 4: 16-bit (70-byte) and 32-bit (140-byte) pcount=31 call-gate
 *            frames on a B=0 stack with SP < frame size.
 *   group 3: V86 permitted controls (9/10-slot frames on wrapped stacks).
 *
 * Every deny case runs twice by construction: the first trigger faults
 * (#PF err=2, CR2 = the first denied-page slot in push order, OLD context,
 * zero frame bytes), the CPL3 #PF handler restores the PTE and the restarted
 * trigger delivers onto the now-present wrapped stack, where the CPL0
 * handler verifies EVERY frame byte against the known constants (the
 * permitted control).  The whole flow is fully differential vs the QEMU
 * golden: QEMU 8.2.2 pushes the same slots in the same order and faults on
 * the same first denied-page push with the same CR2 (seg_helper.c
 * do_interrupt_protected PUSHL/PUSHW: sp decremented first, slot 0 at
 * esp0-unit; cputlb.c mmu_lookup reports the second page's base for a
 * straddling push).  QEMU's partial frame writes on the pages it reached
 * before the fault are not architecturally visible (no trace field carries
 * memory), so the flows compare EQUIVALENT; the RTL's stronger zero-bytes
 * property is graded separately by the pxwrapm witness image.
 *
 * Memory plan (paged protected mode, 4 KiB pages, linear==physical below
 * 1 MiB except the 4 GiB-wrap window):
 *   GDT @ 0x6000 (limit 0x77): 0x08 code0 / 0x10 data0 / 0x18 code3 /
 *     0x20 data3 (flat) / 0x28 TSS (0x3000) / 0x30 ss16 dyn (B=0, base per
 *     case) / 0x38 call gate dyn / 0x40 code0f (D=1 base 0xF0000: 16-bit
 *     gate targets) / idx 9..14 zero (idx 12 non-present: the #GP trigger).
 *   IDT @ 0x1000: [13] dyn (gp0h16 or v86mon), [14] pf3_handler (CS=0x1B,
 *     0x8F), [0x30] dyn per case, [0x31] setup_handler (CS=0x40, 0xEF).
 *   TSS @ 0x3000 (ESP0/SS0 per case, IOPB=0x68).
 *   PD @ 0x10000: PD[0]->PT0 @ 0x11000 identity [0,1MiB) all P|RW|US;
 *     PD[1023]->PT1 @ 0x12000: 0xFFFFE000->phys 0xB0000, 0xFFFFF000->0xC0000.
 *   CPL3 user stack top 0xF000 (upper ESP bits ZERO so the B=0 SET_ESP
 *     high-word leak is a no-op); CG param sources at 0xEF00/0xEE80; clean
 *     CPL0 stack 0xA0000; wrapped 16-bit stacks base 0x80000/0x80FF0/0x80FFC;
 *     case state @ 0x5000; V86 task CS=0xF000 SS=0x2000 ESP=0x8000.
 *
 * GNU-as; no nasm.  Flat 64 KiB -bios image; reset F000:FFF0.
 */

    .code16
    .section .text16, "ax"
    .global _start16
_start16:
    cli
    cld
    xorw    %ax, %ax
    movw    %ax, %ds
    movw    %ax, %es
    movw    %ax, %ss
    movw    $0x9000, %sp

    /* GDT @ 0x6000 */
    movl    $0x00000000, 0x6000         /* 0x00 null */
    movl    $0x00000000, 0x6004
    movl    $0x0000FFFF, 0x6008         /* 0x08 code0 flat */
    movl    $0x00CF9A00, 0x600C
    movl    $0x0000FFFF, 0x6010         /* 0x10 data0 flat */
    movl    $0x00CF9200, 0x6014
    movl    $0x0000FFFF, 0x6018         /* 0x18 code3 flat */
    movl    $0x00CFFA00, 0x601C
    movl    $0x0000FFFF, 0x6020         /* 0x20 data3 flat */
    movl    $0x00CFF200, 0x6024
    movl    $0x30000067, 0x6028         /* 0x28 TSS32 base 0x3000 limit 0x67 */
    movl    $0x00008900, 0x602C
    /* 0x30 ss16 dyn / 0x38 call gate dyn: zeroed by the IDT/GDT scrub below
     * (never installed yet; setup_handler fills them per case). */
    movl    $0x0000FFFF, 0x6040         /* 0x40 code0f: D=1 DPL0 base 0xF0000 */
    movl    $0x00409A0F, 0x6044
    movl    $0x0000FFFF, 0x6048         /* 0x48 code3f: D=1 DPL3 base 0xF0000 */
    movl    $0x0040FA0F, 0x604C         /* (CPL3 code: 16-bit frames carry offsets) */
    movw    $0x0077, 0x0480             /* 15 entries */
    movl    $0x00006000, 0x0482
    lgdt    0x0480

    movl    %cr0, %eax
    orl     $0x1, %eax
    movl    %eax, %cr0
    .byte   0x66, 0xEA
    .long   pm32_entry
    .word   0x08

    .code32
    .section .text32, "ax"
    .global pm32_entry
pm32_entry:
    movw    $0x10, %ax
    movw    %ax, %ds
    movw    %ax, %es
    movw    %ax, %ss
    movw    %ax, %fs
    movw    %ax, %gs
    movl    $0x000A0000, %esp           /* clean CPL0 stack */

    /* zero the IDT @ 0x1000 */
    movl    $0x00001000, %edi
    xorl    %eax, %eax
    movl    $512, %ecx
1:  movl    %eax, (%edi)
    addl    $4, %edi
    loop    1b

    /* IDT[14] #PF -> pf3_handler, CS=0x1B (SAME-priv at CPL3), 32-bit trap
     * gate 0x8F DPL0 (HW faults bypass the gate DPL check). */
    movl    $(pf3_handler - 0xF0000), %ebx
    movl    $0x8F, %eax
    movl    $0x1070, %edi
    movl    $0x004B, %ecx
    call    write_idt_gate_sel

    /* IDT[0x31] -> setup_handler, CS=0x40, 32-bit trap 0xEF DPL3 */
    movl    $(setup_handler - 0xF0000), %ebx
    movl    $0xEF, %eax
    movl    $0x1188, %edi
    movl    $0x0040, %ecx
    call    write_idt_gate_sel

    movw    $0x07FF, 0x0490
    movl    $0x00001000, 0x0492
    lidt    0x0490

    /* TSS @ 0x3000 */
    movl    $0x00003000, %edi
    xorl    %eax, %eax
    movl    $26, %ecx
1:  movl    %eax, (%edi)
    addl    $4, %edi
    loop    1b
    movw    $0x0068, 0x00003066         /* I/O map base: empty map */
    movl    $0x000A0000, 0x00003004     /* ESP0 (clean until case 1 runs) */
    movl    $0x00000010, 0x00003008     /* SS0 = data0 */
    movw    $0x0028, %ax
    ltr     %ax

    /* page tables: PD @ 0x10000, PT0 @ 0x11000 identity [0,1MiB) 0x7,
     * PT1 @ 0x12000 for the 4 GiB-wrap window */
    movl    $0x00011007, 0x00010000     /* PD[0] -> PT0 */
    movl    $0x00012007, 0x00010FFC     /* PD[1023] -> PT1 */
    movl    $0x00011000, %edi
    xorl    %eax, %eax
1:  movl    %eax, %edx
    orl     $0x00000007, %edx
    movl    %edx, (%edi)
    addl    $4, %edi
    addl    $0x1000, %eax
    cmpl    $0x00100000, %eax
    jb      1b
    movl    $0x00400007, 0x00012FF8     /* PT1[0x3FE]: 0xFFFFE000 -> 4 MiB */
    movl    $0x00401007, 0x00012FFC     /* PT1[0x3FF]: 0xFFFFF000 -> 4 MiB+4K
                                         * (NOT 0xB0000/0xC0000: the VGA/ROM
                                         * hole swallows writes under QEMU) */

    movl    $0x00010000, %eax
    movl    %eax, %cr3
    movl    %cr0, %eax
    orl     $0x80000000, %eax
    movl    %eax, %cr0

    /* CG param sources: dword i at 0xEF80+4i = 0xD0000000+i;
     * word i at 0xEFC0+2i = 0xD000+i */
    movl    $31, %ecx
    movl    $0x0000EF00, %edi           /* CG32 dword params at 0xEF00 (the
                                         * #PF frame lands at 0xEFF0..0xEFFF) */
    movl    $0xD0000000, %eax
1:  movl    %eax, (%edi)
    addl    $4, %edi
    incl    %eax
    loop    1b
    movl    $31, %ecx
    movl    $0x0000EE80, %edi           /* CG16 word params at 0xEE80 (the */
    movl    $0x0000D000, %eax           /* CG32 dword area ends at 0xEFFB) */
1:  movw    %ax, (%edi)
    addl    $2, %edi
    incl    %eax
    loop    1b

    movl    $0, 0x5000                  /* cur_case */
    movl    $0, 0x5014                  /* pf3 visit count */
    movw    $0x0061, 0x500C             /* the #GP trigger's selector */
    jmp     setup_handler

/* write_idt_gate_sel: ebx=offset, eax=attr byte, edi=slot addr, ecx=selector */
write_idt_gate_sel:
    movl    %ebx, %edx
    andl    $0x0000FFFF, %edx
    shll    $16, %ecx
    orl     %ecx, %edx
    movl    %edx, (%edi)
    movl    %ebx, %edx
    andl    $0xFFFF0000, %edx
    shll    $8, %eax
    orl     %eax, %edx
    movl    %edx, 4(%edi)
    ret

/* ================= per-case setup (CPL0, clean stack) ==================== */
    .align 16
    .global setup_handler
setup_handler:
    movw    $0x10, %ax                  /* int31 may have landed on a wrapped */
    movw    %ax, %ss                    /* B=0 stack -- switch to a clean SS */
    movl    $0x000A0000, %esp           /* reset the clean stack */
    movl    0x5000, %eax
    cmpl    $NCASES, %eax
    jae     all_done
    incl    %eax
    movl    %eax, 0x5000                /* cur_case = consumed+1 from now on */
    decl    %eax
    shll    $4, %eax
    leal    case_table(%eax), %esi      /* esi = case descriptor */
    movb    (%esi), %al
    movb    %al, 0x5004                 /* cur_kind */

    /* TSS.ESP0/SS0 */
    movl    4(%esi), %eax
    movl    %eax, 0x00003004
    cmpb    $0, 1(%esi)
    jne     1f
    /* build the B=0 ss16 descriptor at GDT[6] (base per case, G=1 lim 0xFFFFF) */
    movl    8(%esi), %eax
    movzwl  %ax, %ebx
    shll    $16, %ebx
    orl     $0x0000FFFF, %ebx
    movl    %ebx, 0x6030
    movl    8(%esi), %eax
    andl    $0x00FF0000, %eax
    shrl    $16, %eax
    movl    8(%esi), %ebx
    andl    $0xFF000000, %ebx
    orl     %ebx, %eax
    orl     $0x008F9200, %eax           /* access 0x92, gran 0x8F (G=1,B=0) */
    movl    %eax, 0x6034
    movl    $0x00000030, %eax
    jmp     2f
1:  movl    $0x00000010, %eax
2:  movl    %eax, 0x00003008

    /* IDT[13]: GP kinds -> gp0h16 (16-bit trap 0x87 DPL0); V86GP -> v86mon
     * (32-bit trap 0x8F DPL0); other kinds leave it zero. */
    movzbl  (%esi), %eax
    cmpl    $2, %eax
    jne     3f
    movl    $(gp0h16 - 0xF0000), %ebx
    movl    $0x87, %eax
    movl    $0x1068, %edi
    movl    $0x0040, %ecx
    call    write_idt_gate_sel
    jmp     4f
3:  cmpl    $5, %eax
    jne     4f
    movl    $(v86mon - 0xF0000), %ebx
    movl    $0x8F, %eax
    movl    $0x1068, %edi
    movl    $0x0040, %ecx
    call    write_idt_gate_sel
4:

    /* IDT[0x30] / the call gate, per kind */
    movzbl  (%esi), %eax
    cmpl    $3, %eax
    je      setup_cgate
    cmpl    $4, %eax
    jae     setup_v86gate
    /* INT/GP kinds: attr = 0xE0 | type; target int0h16/int0h32/gp0h16 */
    movzbl  3(%esi), %ebx               /* flags */
    movl    %ebx, %ecx
    andl    $2, %ecx                    /* gate16 */
    movl    %ebx, %edx
    andl    $4, %edx                    /* trap */
    movl    $6, %eax
    testl   %edx, %edx
    jz      5f
    movl    $7, %eax
5:  testl   %ecx, %ecx
    jnz     6f
    addl    $8, %eax                    /* 32-bit gate types 0xE/0xF */
6:  orl     $0xE0, %eax                 /* P|DPL3 */
    /* target */
    movl    $(int0h32 - 0xF0000), %ebx
    testl   %ecx, %ecx
    jz      7f
    movl    $(int0h16 - 0xF0000), %ebx
7:  cmpb    $2, (%esi)
    jne     8f
    movl    $(gp0h16 - 0xF0000), %ebx
8:  movl    $0x1180, %edi
    movl    $0x0040, %ecx
    call    write_idt_gate_sel
    jmp     setup_fill

setup_cgate:
    /* GDT[7] call gate: pcount 31, DPL3; 16-bit 0xE4 / 32-bit 0xEC */
    movl    $(cg32_callee - 0xF0000), %ebx
    movl    $0xEC, %eax
    testb   $2, 3(%esi)
    jz      1f
    movl    $(cg16_callee - 0xF0000), %ebx
    movl    $0xE4, %eax
1:  movl    %ebx, %edx
    andl    $0x0000FFFF, %edx
    orl     $0x00400000, %edx           /* CS = code0f */
    movl    %edx, 0x6038
    movl    %ebx, %edx
    andl    $0xFFFF0000, %edx
    shll    $8, %eax
    orl     %eax, %edx
    orl     $31, %edx                   /* param count */
    movl    %edx, 0x603C
    jmp     setup_fill

setup_v86gate:
    movl    $(v86mon - 0xF0000), %ebx
    movl    $0xEF, %eax
    movl    $0x1180, %edi
    movl    $0x0040, %ecx
    call    write_idt_gate_sel

setup_fill:
    /* sentinel-fill the frame extent with 0xCC:
     * size = nslots * unit bytes at base + ((esp0 - i) & mask), i = 1..size */
    movzbl  2(%esi), %ecx
    testb   $2, 3(%esi)
    jnz     1f
    shll    $2, %ecx
    jmp     2f
1:  addl    %ecx, %ecx
2:  movl    4(%esi), %edx
    movl    8(%esi), %edi
    cmpb    $0, 1(%esi)
    jne     4f
3:  decl    %edx                        /* B=0: wrap the offset at 64 KiB */
    movzwl  %dx, %edx
    movb    $0xCC, (%edi,%edx)
    loop    3b
    jmp     5f
4:  decl    %edx
    movl    %edx, %eax                /* QEMU wraparound-TLB workaround: a */
    addl    %edi, %eax                /* 4 GiB-straddling push poisons page-0 */
    cmpl    $0x1000, %eax             /* translations; skip low fill bytes */
    jb      6f
    movb    $0xCC, (%edi,%edx)
6:  loop    4b
5:

    /* deny the case's page (0xFFFFFFFF = no denial: permitted controls) */
    movl    12(%esi), %eax
    cmpl    $0xFFFFFFFF, %eax
    je      setup_go
    cmpl    $0xFFC00000, %eax
    jae     1f
    movl    %eax, %ebx
    shrl    $10, %ebx
    movl    $0, 0x11000(%ebx)
    jmp     2f
1:  movl    %eax, %ebx
    shrl    $10, %ebx
    andl    $0xFFC, %ebx
    movl    $0, 0x12000(%ebx)
2:  movl    %cr3, %eax                  /* flush stale translations */
    movl    %eax, %cr3

setup_go:
    movzbl  0x5004, %eax
    cmpl    $4, %eax
    jae     v86_enter
    /* down to CPL3: the stub runs the trigger */
    pushl   $0x00000023
    pushl   $0x0000F000
    pushl   $0x00003202                 /* IF=1 IOPL=3 */
    pushl   $0x0000004B
    pushl   $(cpl3_stub - 0xF0000)
    iretl

/* ======================= V86 entry (kinds 4/5) =========================== */
v86_enter:
    movl    $1, 0x5008                  /* v86_phase: 1 = expect the int30 */
    cmpb    $5, (%esi)
    jne     1f
    movl    $0, 0x5008                  /* kind 5: the CLI #GP comes first */
1:  pushl   $0x00000000                 /* GS */
    pushl   $0x00000000                 /* FS */
    pushl   $0x00002000                 /* DS */
    pushl   $0x00002000                 /* ES */
    pushl   $0x00002000                 /* SS */
    pushl   $0x00008000                 /* ESP */
    cmpb    $5, (%esi)
    je      2f
    pushl   $0x00023002                 /* EFLAGS: VM | IOPL=3 */
    pushl   $0x0000F000                 /* CS */
    pushl   $(v86_task_int - 0xF0000)
    iretl
2:  pushl   $0x00020002                 /* EFLAGS: VM | IOPL=0 */
    pushl   $0x0000F000
    pushl   $(v86_task - 0xF0000)
    iretl

/* ============================ CPL3 stub ================================= */
    .align 16
    .global cpl3_stub
cpl3_stub:
    movl    $0x0000F000, %esp           /* reset the user stack */
    movw    $0x23, %ax
    movw    %ax, %ds
    movzbl  0x5004, %eax
    cmpl    $3, %eax
    je      trig_cg_setup
    cmpl    $2, %eax
    je      trig_gp
    .global trig_int
trig_int:
    int     $0x30
    .global trig_int_ret
trig_int_ret:                           /* pushed return EIP of int $0x30 */
    jmp     trig_done
trig_gp:
    .global trig_gp_fault
trig_gp_fault:
    movw    0x500C, %ds                 /* #GP(0x60): GDT idx 12 non-present;
                                         * selector from MEMORY: the #PF
                                         * handler's regs survive the restart */
    .global trig_gp_after
trig_gp_after:
    jmp     trig_done
trig_cg_setup:
    movl    0x5000, %eax
    decl    %eax
    shll    $4, %eax
    leal    case_table(%eax), %eax
    testb   $2, 3(%eax)
    jz      1f
    movl    $0x0000EE80, %esp           /* 16-bit gate: 31 word params above */
    jmp     trig_cg
1:  movl    $0x0000EF00, %esp           /* 32-bit gate: 31 dword params above */
    .global trig_cg
trig_cg:
    .byte   0x9A                        /* lcall ptr16:32 through gate 0x38 */
    .long   0
    .word   0x003B
    .global trig_done
trig_done:
    int     $0x31                       /* back to CPL0 for the next case */
    jmp     cpl3_stub

/* ================== CPL3 #PF handler (same-priv) ======================== *
 * Reached ONLY when the frame probe faulted in the OLD context: err=2
 * (supervisor write, not present), pushed CS = 0x1B, pushed EIP = the
 * trigger (restart semantics).  Restores the denied PTE and IRETs back; the
 * restarted trigger then delivers onto the now-present wrapped stack (the
 * permitted control).  Never reads the destination pages: QEMU leaves
 * partial pushes there, and reading them would break the differential. */
    .align 16
    .global pf3_handler
pf3_handler:
    incl    0x5014                      /* one probe fault handled */
    cmpl    $2, 0(%esp)                 /* err = {US=0,W=1,P=0} */
    jne     fail
    cmpl    $0x4B, 8(%esp)              /* pushed CS: the OLD CPL3 context */
    jne     fail
    movzbl  0x5004, %eax
    cmpl    $1, %eax
    jne     1f
    cmpl    $(trig_int - 0xF0000), 4(%esp)
    jne     fail
    jmp     3f
1:  cmpl    $2, %eax
    jne     2f
    cmpl    $(trig_gp_fault - 0xF0000), 4(%esp)
    jne     fail
    jmp     3f
2:  cmpl    $3, %eax
    jne     fail                        /* kinds 4/5 never come here */
    cmpl    $(trig_cg - 0xF0000), 4(%esp)
    jne     fail
3:  /* restore the denied PTE */
    movl    0x5000, %eax
    decl    %eax
    shll    $4, %eax
    leal    case_table(%eax), %esi
    movl    12(%esi), %ebx
    movl    %ebx, %eax
    cmpl    $0xFFC00000, %eax
    jae     1f
    shrl    $10, %ebx
    orl     $0x00000007, %eax           /* PT0: identity */
    movl    %eax, 0x11000(%ebx)
    jmp     2f
1:  subl    $0xFFFFF000, %eax
    addl    $0x00401007, %eax           /* PT1: 0xFFFFF000->4MiB+4K, E->4MiB */
    shrl    $10, %ebx
    andl    $0xFFC, %ebx
    movl    %eax, 0x12000(%ebx)
2:  addl    $4, %esp                    /* drop the error code */
    iretl                               /* saved EIP = the trigger: refire */

/* ==================== CPL0 delivery handlers ============================ *
 * Each runs on the WRAPPED stack after the permitted refire and verifies
 * every frame byte against the known constants.  On success each re-arms
 * SS0:ESP0 = 0x10:0xA0000 so the stub's int $0x31 lands on the good stack.
 *
 * Frame-slot reads CANNOT use [esp+disp]: an explicit 32-bit-address-size
 * memory operand does NOT wrap its effective address at the B=0 64 KiB
 * boundary (only stack operations do -- QEMU gen_lea_v_seg MO_32 adds the
 * SS base to the unmasked 32-bit EA), while the frame's slots sit at
 * sp_mask-wrapped offsets.  So every slot address here is computed by hand
 * as ss_base + ((esp + disp) & mask), read through the flat DS. */
    .align 16
    .global int0h16
int0h16:                                /* 16-bit gate, no err: IP CS FL SP SS */
    movl    0x5000, %eax
    decl    %eax
    shll    $4, %eax
    leal    case_table(%eax), %eax
    movl    8(%eax), %edx               /* ss_base */
    movzwl  %sp, %eax
    movzwl  (%eax,%edx), %eax
    cmpl    $(trig_int_ret - 0xF0000), %eax
    jne     fail
    movl    %esp, %eax
    addl    $2, %eax
    movzwl  %ax, %eax
    movzwl  (%eax,%edx), %eax
    cmpl    $0x4B, %eax
    jne     fail
    movl    %esp, %eax
    addl    $4, %eax
    movzwl  %ax, %eax
    movzwl  (%eax,%edx), %eax
    andl    $0x00003302, %eax           /* IOPL|IF|bit1: status bits are live */
    cmpl    $0x3202, %eax
    jne     fail
    movl    %esp, %eax
    addl    $6, %eax
    movzwl  %ax, %eax
    movzwl  (%eax,%edx), %eax
    cmpl    $0xF000, %eax
    jne     fail
    movl    %esp, %eax
    addl    $8, %eax
    movzwl  %ax, %eax
    movzwl  (%eax,%edx), %eax
    cmpl    $0x23, %eax
    jne     fail
    movl    $0x000A0000, 0x00003004
    movl    $0x00000010, 0x00003008
    iretw

